const nextMailTriageAccountDue = `-- name: NextMailTriageAccountDue :one
SELECT q.account_id, q.workspace_id, q.user_id
FROM mail_triage_queue q
JOIN mail_accounts a ON a.id = q.account_id
WHERE a.enabled = true
  AND (
    q.status = 'pending'
    OR (q.status = 'claimed' AND q.claimed_at < $1::timestamptz)
  )
  AND q.attempts < $2::int
ORDER BY q.created_at ASC
LIMIT 1
`

type NextMailTriageAccountDueParams struct {
	StaleBefore time.Time
	MaxAttempts int32
}

type NextMailTriageAccountDueRow struct {
	AccountID   uuid.UUID
	WorkspaceID uuid.UUID
	UserID      uuid.UUID
}

// Finds one enabled account that has pending (or stale claimed) triage queue items.
func (q *Queries) NextMailTriageAccountDue(ctx context.Context, arg NextMailTriageAccountDueParams) (NextMailTriageAccountDueRow, error) {
	row := q.db.QueryRow(ctx, nextMailTriageAccountDue, arg.StaleBefore, arg.MaxAttempts)
	var i NextMailTriageAccountDueRow
	err := row.Scan(&i.AccountID, &i.WorkspaceID, &i.UserID)
	return i, err
}

